mapper.sql:
WHERE status >= 0 AND company_id IN (SELECT company_id FROM user_companies WHERE user_id = #{userId})

    AND request_stocks.date = #{filter.date}


    AND (from_location.id = #{filter.warehouseId} OR to_location.id = #{filter.warehouseId})


    AND request_stocks.status = #{filter.status}


    AND (
    request_stocks.code LIKE CONCAT('%', #{filter.searchText}, '%')
    OR from_location.name LIKE CONCAT('%', #{filter.searchText}, '%')
    OR to_location.name LIKE CONCAT('%', #{filter.searchText}, '%')
    )


    AND request_stocks.created_by = #{userId}

mapper.select:
SELECT



 ORDER BY


        ${filter.orderBy}


          request_stocks.id DESC


 LIMIT #{filter.page}, #{filter.rowsPerPage}

mapper.update:
UPDATE request_stocks SET
                   is_approve = #{requestStockApprove.status},
                   approved= Now(),
                   approved_by = #{requestStockApprove.approvedBy}
WHERE id = #{requestStockApprove.id};

UPDATE request_stocks SET
  status = -1,
  modified = NOW(),
  modified_by = #{userId}
WHERE id = #{id};

UPDATE request_stocks SET
   status = 0,
   modified = NOW(),
   modified_by = #{userId}
WHERE id = #{id};

mapper.select:
SELECT code
FROM request_stocks
WHERE id = #{id}
